function bloqueiaMultiplasAbas(nomePagina, contextPath, habilitarMultiplasAbas) {
    console.log(habilitarMultiplasAbas);

    if (nomePagina === "comanda_" || habilitarMultiplasAbas === "true") {
        return;
    }

    var isSafari = /^((?!chrome|android).)*safari/i.test(navigator.userAgent);
    var isIpad = /iPad|Macintosh/i.test(navigator.userAgent) && 'ontouchend' in document;
    var isAndroidTablet = /Android/i.test(navigator.userAgent) && !/Mobile/i.test(navigator.userAgent);

    var pageKey = nomePagina + window.location.pathname;
    var tokenValidityPeriod = 5000;
    var tabUniqueId = 'tab_' + new Date().getTime() + '_' + Math.random();

    var existingToken = localStorage.getItem(pageKey);
    var currentTime = new Date().getTime();

    if (existingToken) {
        var tokenData = JSON.parse(existingToken);
        var tokenTimestamp = tokenData.timestamp;
        var controllingTab = tokenData.tabId;

        if (currentTime - tokenTimestamp < tokenValidityPeriod && controllingTab !== tabUniqueId) {
            alert("Este módulo já está aberto em outra aba!");

            console.log("Context Path: " + contextPath);
            window.location.href = contextPath + "/pages/privado/index.xhtml";
            return;
        } else {
            localStorage.removeItem(pageKey);
        }
    }

    var newToken = {
        timestamp: new Date().getTime(),
        tabId: tabUniqueId
    };
    localStorage.setItem(pageKey, JSON.stringify(newToken));

    function removeToken() {
        var currentToken = JSON.parse(localStorage.getItem(pageKey));
        if (currentToken && currentToken.tabId === tabUniqueId) {
            localStorage.removeItem(pageKey);
        }
    }

    window.addEventListener('beforeunload', removeToken);

    // Adiciona o evento pagehide para garantir que o token seja removido em dispositivos iOS
    window.addEventListener('pagehide', removeToken);

    setInterval(function() {
        var currentToken = JSON.parse(localStorage.getItem(pageKey));
        if (currentToken && currentToken.tabId === tabUniqueId) {
            localStorage.setItem(pageKey, JSON.stringify({
                timestamp: new Date().getTime(),
                tabId: tabUniqueId
            }));
        }
    }, 2000);

    setInterval(function() {
        var currentToken = JSON.parse(localStorage.getItem(pageKey));
        if (currentToken) {
            var tokenTimestamp = currentToken.timestamp;
            if (new Date().getTime() - tokenTimestamp > tokenValidityPeriod) {
                localStorage.removeItem(pageKey);
            }
        }
    }, 2000);

    if (isSafari && isIpad || isAndroidTablet) {
        document.addEventListener('touchstart', function() {
            var currentToken = JSON.parse(localStorage.getItem(pageKey));
            if (currentToken && new Date().getTime() - currentToken.timestamp > tokenValidityPeriod) {
                localStorage.removeItem(pageKey);
            }
        });
    }
}

