                    break;
            i = (i + 1) % elemento.form.elements.length;
            elemento.form.elements[i].focus();
            elemento.form.elements[i].select();
            event.preventDefault();
            return false;
        }
        return false;
    } else {
        var keyCode = tecla.which;
        if (keyCode === 13) {
