function alterarCoresWhiteLabel(corPrimaria, corSecundaria){

    const variableCss = document.documentElement.style;
    if(corPrimaria !== ""){
        variableCss.setProperty('--azul-avante', corPrimaria);
    }
    if(corSecundaria !== ""){
        variableCss.setProperty('--azul-soft', corSecundaria);
    }

}
