var ultimoTipoDetectado = null;


function mascaraCpfCnpj(widgetVar) {
    // pega o elemento do input pelo widgetVar do PrimeFaces
    var widget = PF(widgetVar);
    if (!widget || !widget.jq || widget.jq.length === 0) {
        return;
    }

    var el = widget.jq[0];

    // Remove a máscara, preservando letras e números
    var v = el.value
        .toUpperCase()
        .replace(/[^A-Z0-9]/g, '');

    if (!v) {
        ultimoTipoDetectado = null;
        el.value = '';
        return;
    }

    var tipo = v.length > 11 ? 'J' : 'F';

    if (tipo === 'F') {
        // CPF: limita a 11 dígitos
        if (v.length > 11) v = v.substring(0, 11);

        v = v.replace(/(\d{3})(\d)/, '$1.$2');
        v = v.replace(/(\d{3})(\d)/, '$1.$2');
        v = v.replace(/(\d{3})(\d{1,2})$/, '$1-$2');
    } else {
        // CNPJ: aceita letras e números
        v = v
            .toUpperCase()
            .replace(/[^A-Z0-9]/g, '');

        // Limita a 14 caracteres
        v = v.substring(0, 14);

        v = v.replace(/([A-Z0-9]{2})([A-Z0-9])/, '$1.$2');
        v = v.replace(/([A-Z0-9]{3})([A-Z0-9])/, '$1.$2');
        v = v.replace(/([A-Z0-9]{3})([A-Z0-9])/, '$1/$2');
        v = v.replace(/([A-Z0-9]{4})([A-Z0-9]{1,2})$/, '$1-$2');
    }

    el.value = v;

    // só atualiza o controle de tipo em memória
    if (tipo !== ultimoTipoDetectado) {
        ultimoTipoDetectado = tipo;
    }
}


function validarCpfCnpj(widgetVar) {
    var widget = PF(widgetVar);
    if (!widget || !widget.jq || widget.jq.length === 0) {
        return;
    }

    var el = widget.jq[0];
    // Remove a máscara, preservando letras e números
    var digits = el.value
        .toUpperCase()
        .replace(/[^A-Z0-9]/g, '');

    if (digits.length !== 11 && digits.length !== 14) {
        el.value = '';
        ultimoTipoDetectado = null;
        return;
    }

    var tipo = digits.length === 11 ? 'F' : 'J';
    // aqui você pode chamar o remoteCommand se quiser
    atualizarTipoCliente([{ name: 'tipoCliente', value: tipo }]);
}

