let manualEdit = false;
let lastActionWasBackspace = false;

function moveToNextTOTP(e, previousInputId, currentInput, nextInputId) {
    const isDigit = (e.keyCode >= 48 && e.keyCode <= 57) || (e.keyCode >= 96 && e.keyCode <= 105);
    const isBackspace = e.keyCode === 8;

    if (isBackspace) {
        lastActionWasBackspace = true;

        if (currentInput.value.length === 0) {
            const prev = document.getElementById(previousInputId);
            if (prev) prev.focus();
        }

        manualEdit = false;
        return;
    }

    if (isDigit) {
        if (lastActionWasBackspace) {
            currentInput.value = e.key;
            e.preventDefault();
            lastActionWasBackspace = false;
            manualEdit = false;
            return;
        }

        const isLastField = !nextInputId;

        if (manualEdit) {
            currentInput.value = e.key;
            e.preventDefault();
        } else if (currentInput.value.length === currentInput.maxLength && !isLastField) {
            const next = document.getElementById(nextInputId);
            if (next) {
                next.focus();
                next.value = e.key;
                e.preventDefault();
            }
        }
    }

    manualEdit = false;
}

